import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Day07 · 目标证据、委派与个人上下文","description":"","frontmatter":{"title":"Day07 · 目标证据、委派与个人上下文","outline":false},"headers":[],"relativePath":"log/day-07.md","filePath":"log/day-07.md","lastUpdated":1794305977000}'),o={name:"log/day-07.md"};function c(i,t,l,n,h,s){return e(),r("div",null,[...t[0]||(t[0]=[a('<p>2026-11-10 是 Hearth 把“任务能跑”推进到“任务有契约、有交接、有上下文、有验收证据”的一天。当天 56 次提交涉及 522 个文件（+20,709/−52,818）：前半段补上目标预算、截止时间、停止条件、命令与 Git 验证器、审批参数绑定和不确定效果对账；后半段加入持久委派、沙箱、交接证据、渠道幂等、个人本体、Context Broker、标准意图和连接运行时，最后把评测 corpus、评测应用和场景运行器迁出主仓库。</p><p>当天文件删除量很大，主要来自评测栈迁出和模板解耦，不代表产品能力被移除。主仓库保留评测桥接、任务模板、产品服务和运行证据；评测 case、控制台、实验和场景证据改由独立仓库维护。</p><h2 id="目标与完成证据" tabindex="-1">目标与完成证据 <a class="header-anchor" href="#目标与完成证据" aria-label="Permalink to &quot;目标与完成证据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>目标预算与停止</td><td>目标预算覆盖轮次、工具调用、Token、时长和人工分钟；截止时间、停止条件和复核策略进入调度，耗尽时暂停、降级或转人工</td></tr><tr><td>验证器</td><td>完成判定新增命令和 Git 验证器，支持文件、结构、人工和模型复核；命令在受限环境中运行，不能用验证器扩权</td></tr><tr><td>调度接入</td><td>调度器在任务准备结束时注入自定义验证器并保存完成报告；目标型任务没有结论不能关闭</td></tr><tr><td>交接证据</td><td>跨执行器交接后仍保留终态证据，旧代次迟到的结果不能覆盖新状态</td></tr><tr><td>界面</td><td>任务详情展示验收条件、完成结论、证据和缺失项，不再只显示执行器总结</td></tr></tbody></table><h2 id="委派、交接与沙箱" tabindex="-1">委派、交接与沙箱 <a class="header-anchor" href="#委派、交接与沙箱" aria-label="Permalink to &quot;委派、交接与沙箱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>持久委派</td><td>父任务创建有界子任务，记录预算、工作区策略、父子关系、租约、心跳和失败状态；子任务通过调度器推进</td></tr><tr><td>工作区策略</td><td>只读、隔离写入和共享读取三种策略约束子任务能看到和写入的范围</td></tr><tr><td>沙箱</td><td>检查工作目录、读写路径、网络域、进程白名单和凭据边界；任何越界失败关闭并留下原因</td></tr><tr><td>交接包</td><td>记录目标、下一步、验收条件、证据、权限子集、上下文水位、代次和脱敏信息；验证通过后才允许继续</td></tr><tr><td>渠道幂等</td><td>飞书和其他渠道的入站事件按标识去重，重复投递不会生成两个任务、两次审批或两个子任务</td></tr></tbody></table><h2 id="个人上下文与注意力" tabindex="-1">个人上下文与注意力 <a class="header-anchor" href="#个人上下文与注意力" aria-label="Permalink to &quot;个人上下文与注意力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>个人本体</td><td>实体、别名、关系、状态、决定和承诺进入统一记录；状态冲突不会被静默覆盖，而是进入需要用户确认的注意力项</td></tr><tr><td>Context Broker</td><td>按聊天、任务、目标、交接和委派范围组装 Context Pack，分为必须知道、相关、可召回和已省略；支持引用展开和父包权限约束</td></tr><tr><td>记忆治理</td><td>记忆来源、可信度、污染状态、敏感度和有效期参与召回；合并可审计，遗忘传播到投影、版本、事件、同步和派生记忆</td></tr><tr><td>标准意图</td><td>用户长期关注的规则保存为标准意图；心跳根据意图和任务状态生成候选，说明为什么现在、下一步和不处理的后果</td></tr><tr><td>注意力预算</td><td>每日上限、安静时段、同类冷却、单目标和高优先级上限、忽略惩罚和 <code>NO_REPLY</code> 反馈共同控制打扰</td></tr><tr><td>连接运行时</td><td>transport、subscription、dataFreshness 和 executionOwnership 分开；重连推进 generation，旧代次写入被拒绝，离线操作进入 outbox，缓存投影不冒充实时</td></tr></tbody></table><h2 id="审批、技能与调度边界" tabindex="-1">审批、技能与调度边界 <a class="header-anchor" href="#审批、技能与调度边界" aria-label="Permalink to &quot;审批、技能与调度边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>审批绑定</td><td>原生补丁、完全权限动作、GitHub 写入和 SMTP 发送都绑定解析后的真实动作；参数变化、过期和复用会使审批失效</td></tr><tr><td>不确定效果</td><td>断线或回执不确定的外部动作进入显式对账队列，用户可以选择确认、重试或放弃，不盲目重发</td></tr><tr><td>技能权限</td><td>技能按使用来源、权限范围和风险分级；过期技能可清理并回退</td></tr><tr><td>调度补跑</td><td>定时任务支持有界补跑和失败冷却，避免停机后一次补跑过多或失败后高频重试</td></tr><tr><td>测试</td><td>新增目标、完成判定、委派、交接、沙箱、渠道、连接、个人本体、Context Broker、注意力和审批绑定的回归测试</td></tr></tbody></table><h2 id="评测拆分与文档" tabindex="-1">评测拆分与文档 <a class="header-anchor" href="#评测拆分与文档" aria-label="Permalink to &quot;评测拆分与文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>评测独立</td><td>评测前端、评测服务、评测核心、case、场景运行器和文档迁到独立仓库 <code>hearth-eval</code>；主仓库只保留任务/判定桥接和受管 artifact 目录</td></tr><tr><td>模板解耦</td><td>产品任务模板不再依赖评测 corpus，主服务使用自己的示例输入和产物声明</td></tr><tr><td>产物根目录</td><td>任务产物统一落到产品 artifact 根目录，评测输入通过外部根目录授权</td></tr><tr><td>文档事实</td><td>README、交付状态、执行器交接、评测指南和阶段说明同步到拆分后的事实；新增本页与 Day06</td></tr></tbody></table><h2 id="提交记录" tabindex="-1">提交记录 <a class="header-anchor" href="#提交记录" aria-label="Permalink to &quot;提交记录&quot;">​</a></h2><h3 id="_2026-11-10-56-次提交-节选" tabindex="-1">2026-11-10（56 次提交，节选） <a class="header-anchor" href="#_2026-11-10-56-次提交-节选" aria-label="Permalink to &quot;2026-11-10（56 次提交，节选）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>提交</th><th>作者</th><th>修改</th></tr></thead><tbody><tr><td><code>753804b</code></td><td>JasonBuildAI</td><td>目标强制执行轮次、工具、Token、时长和人工分钟预算，并接入截止时间与停止条件；4 个文件（+279/−20）。</td></tr><tr><td><code>442db1d</code></td><td>JasonBuildAI</td><td>完成判定新增命令和 Git 验证器，覆盖测试、差异和工作区证据；2 个文件（+165/−2）。</td></tr><tr><td><code>93c3608</code></td><td>JasonBuildAI</td><td>调度器注入自定义验证器并保存完成报告；2 个文件（+73/−2）。</td></tr><tr><td><code>0c778d1</code></td><td>JasonBuildAI</td><td>任务详情展示验收条件、完成结论和缺失证据；多文件。</td></tr><tr><td><code>47c9517</code></td><td>JasonBuildAI</td><td>原生补丁和完全权限动作绑定解析后的真实动作，参数变化会使审批失效；3 个文件（+144/−24）。</td></tr><tr><td><code>4e73449</code></td><td>JasonBuildAI</td><td>暴露不确定效果的对账队列和人工处理入口；10 个文件（+394/−9）。</td></tr><tr><td><code>61c849d</code></td><td>JasonBuildAI</td><td>新增单层持久委派任务，记录预算、工作区策略、父子关系与失败状态；2 个文件（+695）。</td></tr><tr><td><code>2a232e8</code></td><td>JasonBuildAI</td><td>沙箱强制路径、网络和凭据边界，越界失败关闭；2 个文件（+249）。</td></tr><tr><td><code>90920ba</code></td><td>JasonBuildAI</td><td>交接验证生成代次并持久化交接证据，旧代次迟到结果不能覆盖新状态；7 个文件（+1,109/−15）。</td></tr><tr><td><code>be5112d</code></td><td>JasonBuildAI</td><td>飞书入站消息持久化幂等键，重复投递不重复创建任务或审批；3 个文件（+177/−35）。</td></tr><tr><td><code>4bb5b1d</code></td><td>JasonBuildAI</td><td>新增个人本体、Context Broker 和注意力运行时；51 个文件（+7,840/−140）。</td></tr><tr><td><code>4e0ecce</code></td><td>JasonBuildAI</td><td>新增标准意图、心跳和注意力队列，按预算与反馈决定是否送达；7 个文件（+1,607/−3）。</td></tr><tr><td><code>32877f2</code></td><td>JasonBuildAI</td><td>新增 generation 归属的连接运行时、离线 outbox 和缓存投影；9 个文件（+1,475/−5）。</td></tr><tr><td><code>5a7ece2</code></td><td>JasonBuildAI</td><td>过期技能清理与回退；7 个文件（+628/−8）。</td></tr><tr><td><code>d43941d</code></td><td>JasonBuildAI</td><td>技能按范围执行权限检查；7 个文件（+781/−7）。</td></tr><tr><td><code>8dbc39f</code></td><td>JasonBuildAI</td><td>定时任务有界补跑和失败冷却；5 个文件（+785/−58）。</td></tr><tr><td><code>89df4e7</code></td><td>JasonBuildAI</td><td>评测 corpus 与场景运行器迁出主仓库；259 个文件（−42,941）。</td></tr><tr><td><code>cb097b9</code></td><td>JasonBuildAI</td><td>评测前端、评测服务和评测核心迁出主仓库；49 个文件（−8,859）。</td></tr><tr><td><code>f14642c</code></td><td>JasonBuildAI</td><td>产品任务模板与评测 corpus 解耦；2 个文件（+39/−112）。</td></tr></tbody></table><h2 id="边界与下一步" tabindex="-1">边界与下一步 <a class="header-anchor" href="#边界与下一步" aria-label="Permalink to &quot;边界与下一步&quot;">​</a></h2><ul><li>目标完成判定已覆盖命令、文件、结构、Git、人工和模型复核，但主观质量、真实业务影响和真实外部回执仍需人工验收。</li><li>委派是单层的，没有递归子 Agent 团队；本地沙箱是路径、网络、进程和凭据策略检查，不是强隔离容器或虚拟机。</li><li>连接运行时已有 generation、离线 outbox 和缓存投影，但没有接入真实远程节点或手机，未完成真实断网重连与跨节点对账。</li><li>个人本体和 Context Broker 仍以本地启发式匹配和排序为主；真实长期个人数据、手机推送、远程接管和跨设备上下文一致性尚未验收。</li><li>评测栈已迁出主仓库，<code>hearth-eval</code> 中的真实实验和通过率尚未由本轮文档更新产生；主仓库测试不能替代独立评测。</li><li>同日运行 <code>npm test</code>：89 个测试文件、579 个测试全部通过；<code>npm run typecheck</code>、<code>npm run build</code> 和 <code>npm run docs:build</code> 通过。测试通过不等于真实用户、真实设备和长期运行验收完成。</li></ul>',17)])])}const p=d(o,[["render",c]]);export{u as __pageData,p as default};
